/* Renders icons from the vendored HugeIcons definitions (studio/static/vendor/
 * hugeicons.js, window.HUGEICONS, regenerated by studio/tools/icons/build.mjs).
 * No path data lives in this file or is ever typed by hand here: every glyph
 * this produces comes straight from the npm package's own [tag, attrs] arrays.
 *
 * Two ways callers use this:
 *   - Dynamic markup (panels.js, app.js) calls StudioIcons.render(name, cls)
 *     directly and appends the returned <svg> itself, in place of the old
 *     <svg class="cls"><use href="#icon-x"></use></svg> pattern -- same one
 *     element, same class, real <path>/<circle> children instead of a <use>.
 *   - Static markup (index.html) leaves a placeholder element carrying
 *     data-icon="Name" (its own existing classes untouched, so style.css's
 *     sizing rules still match); StudioIcons.mount(root) finds every such
 *     placeholder under root and appends a rendered <svg> into it, sized to
 *     fill the placeholder's own box.
 */
(function (global) {
  "use strict";

  var SVGNS = "http://www.w3.org/2000/svg";

  // "key" is React's own reconciliation hint (see any definition in
  // hugeicons.js): it rides along in the package's data shape but is not a
  // real SVG/HTML attribute, so it is the one name this never sets on an
  // element. Every other attribute name in the vendored data is a standard
  // SVG presentation attribute spelled camelCase (strokeWidth, strokeLinecap,
  // fillRule, ...); real SVG markup spells those kebab-case, so that is the
  // one conversion every attribute name gets.
  function svgAttrName(name) {
    return name.replace(/[A-Z]/g, function (m) { return "-" + m.toLowerCase(); });
  }

  function buildNode(entry) {
    var tag = entry[0];
    var attrs = entry[1] || {};
    var el = document.createElementNS(SVGNS, tag);
    Object.keys(attrs).forEach(function (key) {
      if (key === "key") return;
      el.setAttribute(svgAttrName(key), attrs[key]);
    });
    return el;
  }

  // Returns a standalone <svg>, 24x24 viewBox (every HugeIcons "Stroke
  // Rounded" glyph is drawn on that grid), fill none/stroke currentColor as
  // the sane defaults for an outline icon set, with `cls` applied so a
  // dynamic call site (panels.js, app.js) can hand it the exact class the
  // old <use>-based svg carried and get identical CSS sizing for free. Width
  // and height default to 1em (scale with whatever font-size the icon sits
  // in) for a standalone call with no sizing class; a CSS class overrides
  // that the same way it would override any other presentation attribute,
  // and mount() below (the other caller) sets an explicit 100% instead once
  // it knows the real placeholder box it is filling.
  function render(name, cls) {
    var def = global.HUGEICONS && global.HUGEICONS[name];
    if (!def) {
      throw new Error("StudioIcons.render: unknown icon \"" + name + "\" (not in window.HUGEICONS -- " +
        "add it to studio/tools/icons/build.mjs's ICON_NAMES and regenerate)");
    }
    var svg = document.createElementNS(SVGNS, "svg");
    svg.setAttribute("viewBox", "0 0 24 24");
    svg.setAttribute("width", "1em");
    svg.setAttribute("height", "1em");
    svg.setAttribute("fill", "none");
    svg.setAttribute("stroke", "currentColor");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("data-icon", name);
    if (cls) svg.setAttribute("class", cls);
    def.forEach(function (entry) { svg.appendChild(buildNode(entry)); });
    return svg;
  }

  // Fills every data-icon placeholder under `root` that is not itself
  // already an <svg> (the dynamic call sites above hand render()'s own
  // return value straight into the DOM, which already carries data-icon on
  // itself; querying data-icon and finding an <svg> there means it is
  // already rendered, not a placeholder waiting to be filled) and has not
  // already been filled (a re-run of mount() after DOM churn must not stack
  // a second icon inside the same placeholder).
  function mount(root) {
    var scope = root || document;
    var placeholders = scope.querySelectorAll("[data-icon]");
    for (var i = 0; i < placeholders.length; i++) {
      var el = placeholders[i];
      if (el.tagName.toLowerCase() === "svg") continue; // already a rendered icon, not a placeholder
      if (el.firstElementChild && el.firstElementChild.tagName.toLowerCase() === "svg") continue; // already mounted
      var name = el.getAttribute("data-icon");
      var icon = render(name);
      // Fill the placeholder's own box exactly (that box's size comes from
      // whichever existing class -- .rowicon, .sun, .moon, ... -- the
      // placeholder kept), rather than the 1em default render() otherwise
      // returns for a standalone call with no known container.
      icon.style.width = "100%";
      icon.style.height = "100%";
      el.appendChild(icon);
    }
  }

  global.StudioIcons = { render: render, mount: mount };
})(window);
